import math
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    from collections import defaultdict
    cells=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if g[r][c]!=g[0][0]: cells[g[r][c]].append((r,c))
    bg=g[0][0]
    out=[r[:] for r in g]
    for col,p in list(cells.items()):
        # directions from collinear pairs of points of this color
        dirs=set()
        for i in range(len(p)):
            for j in range(i+1,len(p)):
                a,b=p[i],p[j]
                dr=(b[0]-a[0]); dc=(b[1]-a[1])
                g=math.gcd(abs(dr),abs(dc))
                dirs.add((dr//g,dc//g)); dirs.add((-dr//g,-dc//g))
        if not dirs: continue
        pts=set(p)
        painted={}  # (r,c)->color
        for dr,dc in dirs:
            for start in sorted(pts,key=lambda q:(q[0]*dc-q[1]*dr,0)):
                # rays going both ways from each point along this direction
                for origin,sgn in [(start,1),(start,-1)]:
                    r,c=origin[0]+sgn*dr,origin[1]+sgn*dc
                    while True:
                        if 0<=r<H and 0<=c<W and out[r][c]==bg and (r,c) not in painted:
                            painted[(r,c)]=col; r+=sgn*dr; c+=sgn*dc
                        else: break
    for (r,c),v in painted.items(): out[r][c]=v
    return out
